/**
 * Unit tests for JSTypeRegistry.getType(StaticScope, String, String, int, int).
 */
public class JSTypeRegistry_getType_TriageGen0Test {

    private JSTypeRegistry registry;
    private ErrorReporter errorReporter;
    private StaticScope<JSType> mockScope;

    @Before
    public void setUp() {
        errorReporter = Mockito.mock(ErrorReporter.class);
        registry = new JSTypeRegistry(errorReporter);
        mockScope = Mockito.mock(StaticScope.class);
    }

    /**
     * Tests that if the type already exists (e.g., a native type), 
     * it is returned without creating a new NamedType.
     */
    @Test
    public void testGetType_ExistingNativeType() {
        // "number" is a native type usually pre-registered in JSTypeRegistry
        String typeName = "number";
        JSType expectedType = registry.getType(typeName);

        JSType actualType = registry.getType(mockScope, typeName, "test.js", 1, 1);

        assertNotNull(actualType);
        assertSame("Should return the existing native type", expectedType, actualType);
    }

    /**
     * Tests that if the type does not exist, a new NamedType is created,
     * stored in the unresolvedNamedTypes map for the given scope, and returned.
     */
    @Test
    public void testGetType_NewNamedType() {
        String typeName = "MyCustomType";
        String sourceName = "test.js";
        int line = 10;
        int charNo = 5;

        // First call: creates the type
        JSType type1 = registry.getType(mockScope, typeName, sourceName, line, charNo);

        assertNotNull(type1);
        // Check if it's actually a NamedType (via reflection or behavior if JSType is abstract)
        // Since we can't see NamedType internals, we verify via registry consistency

        // Second call: should return the same instance (interning/caching behavior)
        JSType type2 = registry.getType(mockScope, typeName, sourceName, line, charNo);

        assertSame("Subsequent calls with same name should return same instance", type1, type2);
    }

    /**
     * Tests that different scopes result in different unresolved named types 
     * if the type name is the same but not globally registered.
     * (Note: The implementation uses unresolvedNamedTypes.put(scope, namedType), 
     * which suggests the map is Map<StaticScope, NamedType> or similar. 
     * If the map is Map<String, NamedType>, the scope might be used differently.
     * Based on the provided code: unresolvedNamedTypes.put(scope, namedType);
     * This implies the map key is the scope.)
     */
    @Test
    public void testGetType_DifferentScopes() {
        StaticScope<JSType> scope1 = Mockito.mock(StaticScope.class);
        StaticScope<JSType> scope2 = Mockito.mock(StaticScope.class);
        String typeName = "ScopedType";

        JSType type1 = registry.getType(scope1, typeName, "file1.js", 1, 1);
        JSType type2 = registry.getType(scope2, typeName, "file2.js", 2, 2);

        assertNotNull(type1);
        assertNotNull(type2);
        // Since the code does unresolvedNamedTypes.put(scope, namedType), 
        // and the provided snippet shows type = namedType is returned,
        // if the key is the scope, different scopes will hold different named types.
        // However, the line `JSType type = getType(jsTypeName);` is checked first.
        // If getType(jsTypeName) returns null, it enters the if block.

        // If the implementation logic is: if (getType(jsTypeName) == null) { create and put in map }
        // Then the first call for 'ScopedType' will return a new type.
        // The second call for 'ScopedType' with a DIFFERENT scope will also call getType(jsTypeName),
        // which still returns null (because it's not a native type), thus creating a NEW NamedType.

        // This test verifies the branch where type == null.
        assertNotNull(type1);
        assertNotNull(type2);
    }

    /**
     * Tests the branch where getType(jsTypeName) is NOT null.
     */
    @Test
    public void testGetType_AlreadyDeclaredType() {
        String typeName = "boolean"; // Native type
        JSType existing = registry.getType(typeName);

        // This should trigger the 'if (type == null)' being false
        JSType result = registry.getType(mockScope, typeName, "src.js", 1, 1);

        assertSame(existing, result);
    }

    /**
     * Tests edge case with empty strings.
     */
    @Test
    public void testGetType_EmptyName() {
        String typeName = "";
        JSType type = registry.getType(mockScope, typeName, "src.js", 0, 0);
        assertNotNull(type);
    }
}
